import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Knowledge Base — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Knowledge Base — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/knowledge-base"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Knowledge Base — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/knowledge-base"}]]},"headers":[],"relativePath":"deployment/knowledge-base.md","filePath":"deployment/knowledge-base.md","lastUpdated":1787319539000}'),l={name:"deployment/knowledge-base.md"};function n(s,e,d,r,c,g){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="knowledge-base-—-production-guide" tabindex="-1">Knowledge Base — Production Guide <a class="header-anchor" href="#knowledge-base-—-production-guide" aria-label="Permalink to &quot;Knowledge Base — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>knowledge-base</code>, version <strong>1.0.0</strong></li><li>Category: Operations (<code>operations</code>, category sort <code>40</code>), module sort <code>60</code>, icon <code>book-open</code></li><li><strong>Not</strong> default-included; <strong>not</strong> billable (Marketplace free install; prices <code>$0</code>)</li><li>No hard module dependencies</li><li>Deactivate via Central/Marketplace subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>New workspaces do <strong>not</strong> get Knowledge Base until Marketplace install.</p><ol><li>Run create-table migrations (<code>knowledge_base_categories</code>, <code>knowledge_base_articles</code>, <code>knowledge_base_article_notes</code>, <code>knowledge_base_article_activities</code>)</li><li>Run <code>register_knowledge_base_module</code> + <code>add_knowledge_base_permissions</code> data migrations</li><li>Deploy frontend (<code>src/pages/knowledge-base/</code>, tour <code>knowledge-base</code>)</li><li>Install module on the workspace; refresh SPA session for entitlements</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>Permissions for existing workspaces ship via <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions</code> (additive):</p><ul><li>admin: view / create / update / delete / restore (not <code>force.delete</code>)</li><li>manager: view / create / update</li><li>staff: view</li></ul><p><code>force.delete</code> remains owner/custom grant only unless explicitly assigned.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><p>Platform audit events: <code>knowledge_base_article_created</code>, <code>knowledge_base_article_updated</code>, <code>knowledge_base_article_deleted</code>, <code>knowledge_base_article_note_added</code>.</p><p>Spatie activity log name: <code>knowledge-base</code>. Domain timeline: <code>knowledge_base_article_activities</code>.</p><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate schema + catalog + permissions</li><li>Deploy backend (routes under <code>/api/tenant/v1/knowledge-base*</code> and <code>/knowledge-base-categories*</code>)</li><li>Deploy SPA</li><li>Smoke: Marketplace install → create category → create draft article → publish → staff with view-only sees published only → editor sees drafts/trash → soft delete / restore → confirm category delete blocked while articles use it</li><li>Confirm routes return 403 when module not installed</li><li>Optional: Playwright <code>npm run test:e2e:knowledge-base</code></li></ol>',15)])])}const u=o(l,[["render",n]]);export{m as __pageData,u as default};
